package com.bookstore.infrastructure.repositories;
import com.bookstore.application.sequences.SequenceRepository.SequenceRecord; import java.util.*;
public final class SequenceRepository implements com.bookstore.application.sequences.SequenceRepository { private final Map<String,Long> values=new HashMap<>(); public SequenceRecord getByKey(String key){if(key==null||key.isBlank())throw new IllegalArgumentException("Sequence key is required.");return new SequenceRecord(key,values.getOrDefault(key,0L));} public synchronized long allocateSequence(SequenceRecord sequence){if(sequence==null||sequence.key().isBlank())throw new IllegalArgumentException("Sequence key is required.");long current=values.getOrDefault(sequence.key(),0L);if(current!=sequence.currentValue())throw new IllegalStateException("Sequence '"+sequence.key()+"' changed after it was read.");long next=Math.addExact(current,1);values.put(sequence.key(),next);return next;} public long current(String key){return values.getOrDefault(key,0L);} }
